package com.travelbird.ai.config;
import com.travelbird.ai.client.*;import com.travelbird.global.config.InternalAiProperties;import java.net.http.HttpClient;import java.time.Duration;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.http.client.JdkClientHttpRequestFactory;import org.springframework.web.client.RestClient;
@Configuration(proxyBeanMethods=false) public class AiClientConfig{@Bean AiRecommendationClient aiRecommendationClient(RestClient.Builder b,InternalAiProperties p,@Value("${app.ai.server-base-url}")String url){var h=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();var f=new JdkClientHttpRequestFactory(h);f.setReadTimeout(Duration.ofSeconds(5));return new HttpAiRecommendationClient(b.baseUrl(url).requestFactory(f).build(),p.internalKey());}}
